import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { Tracer, type Span } from "../src/tracing/tracer.ts";
import { LabelBatcher } from "../src/shipping/labelBatcher.ts";
import { labelHandler } from "../src/shipping/handler.ts";
import type { CarrierApi, Shipment } from "../src/shipping/carrier.ts";

function setup(opts: { maxBatch?: number; fail?: boolean } = {}) {
    let n = 0;
    const tracer = new Tracer(() => (++n).toString(16).padStart(16, "0"));
    const calls: string[][] = [];
    const carrier: CarrierApi = {
        async createLabels(shipments) {
            calls.push(shipments.map((s) => s.id));
            await tick();
            if (opts.fail) throw new Error("carrier unavailable");
            return shipments.map((s) => ({ shipmentId: s.id, trackingNumber: `TRK-${s.id}` }));
        },
    };
    const batcher = new LabelBatcher(carrier, tracer, opts.maxBatch);
    return { tracer, calls, handle: labelHandler(tracer, batcher) };
}

const parcel = (id: string): Shipment => ({ id, weightGrams: 1200, postcode: "SW1A 1AA" });
const upstream = (traceHex: string) => ({ traceparent: `00-${traceHex.repeat(32)}-${"a".repeat(16)}-01` });

function spansNamed(tracer: Tracer, name: string): Span[] {
    return tracer.finished.filter((s) => s.name === name);
}

// For each carrier span: the request span it hangs under, matched by shipment.
function carrierParents(tracer: Tracer) {
    const requests = spansNamed(tracer, "POST /shipments/:id/label");
    return spansNamed(tracer, "carrier.createLabels").map((c) => {
        const own = requests.find((r) => r.attributes.shipmentId === c.attributes.shipmentId)!;
        return { shipment: c.attributes.shipmentId, sameTrace: c.traceId === own.traceId, childOfOwnRequest: c.parentId === own.spanId };
    });
}

test("a single label request records the carrier call as a child span", async () => {
    const { tracer, handle } = setup();
    const res = await handle({ headers: {}, shipment: parcel("s1") });
    assert.deepEqual(res, { status: 201, body: { trackingNumber: "TRK-s1" } });
    assert.deepEqual(carrierParents(tracer), [{ shipment: "s1", sameTrace: true, childOfOwnRequest: true }]);
});

test("an incoming traceparent is continued, not replaced", async () => {
    const { tracer, handle } = setup();
    await handle({ headers: upstream("c"), shipment: parcel("s1") });
    const [request] = spansNamed(tracer, "POST /shipments/:id/label");
    assert.equal(request.traceId, "c".repeat(32));
    assert.equal(request.parentId, "a".repeat(16));
});

test("requests made at the same time share one carrier call", async () => {
    const { calls, handle } = setup();
    const results = await Promise.all(["s1", "s2", "s3"].map((id) => handle({ headers: {}, shipment: parcel(id) })));
    assert.deepEqual(calls, [["s1", "s2", "s3"]]);
    assert.deepEqual(results.map((r) => r.body.trackingNumber), ["TRK-s1", "TRK-s2", "TRK-s3"]);
});

test("each batched request's carrier span belongs to that request's own trace", async () => {
    const { tracer, handle } = setup();
    await Promise.all([
        handle({ headers: upstream("1"), shipment: parcel("s1") }),
        handle({ headers: upstream("2"), shipment: parcel("s2") }),
        handle({ headers: upstream("3"), shipment: parcel("s3") }),
    ]);
    const parents = carrierParents(tracer);
    console.log("carrier spans vs. their own request:", parents);
    assert.deepEqual(parents, ["s1", "s2", "s3"].map((shipment) => ({ shipment, sameTrace: true, childOfOwnRequest: true })));
});

test("a full batch is sent straight away and later requests start a new batch", async () => {
    const { tracer, calls, handle } = setup({ maxBatch: 2 });
    await Promise.all(["s1", "s2", "s3"].map((id) => handle({ headers: upstream(id.slice(1)), shipment: parcel(id) })));
    assert.deepEqual(calls, [["s1", "s2"], ["s3"]]);
    assert.ok(carrierParents(tracer).every((p) => p.sameTrace && p.childOfOwnRequest));
});

test("a carrier outage fails every waiting request and marks each one's span as an error", async () => {
    const { tracer, handle } = setup({ fail: true });
    const results = await Promise.all(["s1", "s2"].map((id) => handle({ headers: upstream(id.slice(1)), shipment: parcel(id) })));
    assert.deepEqual(results.map((r) => r.status), [502, 502]);
    const carrierSpans = spansNamed(tracer, "carrier.createLabels");
    assert.deepEqual(carrierSpans.map((s) => [s.status, s.attributes.error]), [["error", "carrier unavailable"], ["error", "carrier unavailable"]]);
    assert.deepEqual(carrierSpans.map((s) => s.traceId), ["1".repeat(32), "2".repeat(32)]);
});

test("an invalid parcel is rejected without calling the carrier", async () => {
    const { tracer, calls, handle } = setup();
    const res = await handle({ headers: {}, shipment: { ...parcel("s9"), weightGrams: 0 } });
    assert.equal(res.status, 400);
    assert.deepEqual(calls, []);
    assert.equal(spansNamed(tracer, "carrier.createLabels").length, 0);
});
